parameters.jsCode:
// Filter and generate warm follow-up messages
const items = $input.all();
const output = [];

for (const item of items) {
  const esc = item.json;
  if (!esc || !esc.id) continue;

  const guestName = esc.guest ? `${esc.guest.first_name} ${esc.guest.last_name}`.trim() : "Guest";
  const followUpText = `Dear ${guestName}, this is a courtesy follow-up from the Grand Azure Front Desk regarding your inquiry: "${esc.inquiry_text.substring(0, 80)}...". Our team is currently reviewing your ticket (Ref #${esc.id}) to ensure everything is resolved to your complete satisfaction. Please let us know if you need anything else in the meantime.`;

  output.push({
    json: {
      escalation_id: esc.id,
      conversation_id: esc.conversation_id,
      guest_id: esc.guest_id,
      guest_name: guestName,
      guest_email: esc.guest ? esc.guest.email : "guest@azurehotel.demo",
      follow_up_message: followUpText,
      generated_at: new Date().toISOString()
    }
  });
}

return output;

